// Build the LLMAlertRequest from raw anomaly data.
// Input: { anomaly_type, event_data, context, few_shot_examples? }
const input = $json;
const request = {
  event_data: input.event_data || {},
  anomaly_type: input.anomaly_type || 'odds_anomaly',
  context: input.context || {},
  few_shot_examples: input.few_shot_examples || []
};
return [{
  json: request
}];

// Call the processing engine LLM client to generate a structured alert.
// In production this invokes processing_engine.alerts.llm_client.generate_alert(request)
// via a Python worker or the LLM node. Here we simulate the structured output schema.
const request = $json;
const anomalyType = request.anomaly_type;
const ctx = request.context || {};

const templates = {
  odds_anomaly: {
    title: 'Odds Anomaly Detected',
    description: 'Odds moved beyond expected threshold vs other providers. Verify the price before accepting bets.',
    severity: 'warning',
    suggested_action: 'Verify with other providers before accepting bets.'
  },
  settlement_discrepancy: {
    title: 'Settlement Discrepancy',
    description: 'Settled outcome disagrees with canonical event result. Review and reconcile before paying out.',
    severity: 'critical',
    suggested_action: 'Reconcile with official result feed and adjust payouts.'
  },
  feed_outage: {
    title: 'Feed Outage Suspected',
    description: 'No updates received from provider within the expected window. Check provider connectivity.',
    severity: 'page',
    suggested_action: 'Check provider feed health and switch to backup provider.'
  },
  arbitrage_detected: {
    title: 'Arbitrage Opportunity',
    description: 'Cross-provider odds imply an arbitrage situation. Review exposure and consider adjusting limits.',
    severity: 'warning',
    suggested_action: 'Review exposure; adjust limits or suspend the market.'
  },
  suspicious_pattern: {
    title: 'Suspicious Betting Pattern',
    description: 'Unusual betting volume or pattern detected. Review for potential fraud.',
    severity: 'critical',
    suggested_action: 'Review account activity and consider limiting the market.'
  },
  reconciliation_drift: {
    title: 'Reconciliation Drift',
    description: 'Checksum comparison found drift between systems for this entity.',
    severity: 'warning',
    suggested_action: 'Investigate drift and apply auto-correction or manual fix.'
  }
};

const template = templates[anomalyType] || templates.odds_anomaly;
const confidence = Number.isFinite(Number(ctx.confidence)) ? Math.min(1, Math.max(0, Number(ctx.confidence))) : 0.85;

return [{
  json: {
    ...template,
    confidence,
    metadata: { anomaly_type: anomalyType, source_event_id: request.event_data.event_id || request.event_data.id },
    llm_request: request
  }
}];

// Route high-confidence alert to auto-escalation (pager / ticket / Slack)
const alert = $json;
return [{
  json: {
    action: 'auto_escalate',
    alert,
    routing: alert.severity === 'page' ? 'pagerduty' : alert.severity === 'critical' ? 'ticket' : 'slack',
    escalated_at: new Date().toISOString()
  }
}];

// Route low-confidence alert to human review queue
const alert = $json;
return [{
  json: {
    action: 'human_review',
    alert,
    review_queue: 'alert-engine-review',
    queued_at: new Date().toISOString()
  }
}];
